  if (!observation.attempted) {
    return {
      path: null,
      bytes: null,
      error: observation.error,
      state: 'UNAVAILABLE',
      partial: false,
    };
  }

  const playable =
    observation.error === null &&
    observation.path !== null &&
    observation.header &&
    observation.bytes !== null &&
    observation.bytes >= MIN_PLAYABLE_RECORDING_BYTES;

